quests[29517] = { id = 29517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes on the Prizes", description = "The games are more popular than ever, and that means we're giving out prizes faster than we ever have before!\n\nWe're going to need more prizes, and fast. If you've some skill in leatherworking, I can give you a kit. You'll need to buy some of the pieces from any trade goods merchant in Elwynn Forest or Mulgore, but they're inexpensive.\n\nAre you willing to help?", sourceObjective = "Use the Darkmoon Craftsman's Kit to make 5 Darkmoon Prizes from Coarse Thread, Shiny Baubles, and Blue Dye.", progress = "Have you had a chance to make those prizes?", completion = "Excellent work! These look just like the others. Thank you for your help.\n\nIf you ever want to help again, look for me next time the Darkmoon Faire is in town.", sourceObjectiveStatus = "unverified-source-field" }
quests[29518] = { id = 29518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rearm, Reuse, Recycle", description = "Faire-goers just love the steam tonks! And when the Darkmoon Faire closes, these grounds will be littered with tonk scrap.\n\nIt'd be a shame to let all that good metal just sit in the dirt.\n\nIf you help me collect some of the larger scraps, I can use them to reforge broken tonk parts. It's a lot less expensive than buying new metal every time. What do you say?", sourceObjective = "Collect 6 pieces of Tonk Scrap from around the Darkmoon Faire grounds.", progress = "Did you manage to find any scrap? The grounds are full of it.", completion = "There's a good bit of scrap here. Thanks for your help. It'll be a big help when I refit the steam tonks.\n\nPlease take this as a reward for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[29519] = { id = 29519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tan My Hide", description = "The Darkmoon Faire always needs more leather for tents, boots, and just about anything you can imagine! I've trapped some creatures and staked the skins out for the next part of their treatment.\n\nYou seem to have some knowledge of skinning. I'll reward you if you help me with the job of scraping some of those new skins.", sourceObjective = "Scrape 4 Staked Skins around the grounds of the Darkmoon Faire.", progress = "It's a busy job keeping the Darkmoon Faire running.", completion = "Thanks for the help, {name}. I'll never forget your contribution to the Darkmoon Faire.\n\nAnd if you feel inclined, come back and help again next time we're in town.", sourceObjectiveStatus = "unverified-source-field" }
quests[29520] = { id = 29520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banners, Banners Everywhere!", description = "Isn't it wonderful to see Darkmoon banners everywhere? It's my favorite part of setting up, but we have so many old and tattered ones that need to be replaced.\n\nIf you've some skill with a needle and thread, would you mind making a banner from this kit and putting it up in some loose stones scattered around the grounds of the faire?\n\nIt's missing a few pieces, but you should be able to get what you need from any trade goods vendor in Elwynn Forest or Mulgore.", sourceObjective = "Use Coarse Thread, Red Dye, and Blue Dye with a Darkmoon Banner Kit to make a Darkmoon Banner, then set it up in a pile of Loose Stones on the grounds of the Darkmoon Faire.", progress = "Were you able to find a place for that new banner of yours?", completion = "Thanks for helping with those banners. You have quite a talent for needlework. Next time the Darkmoon Faire's in town, why not come by and help again?", sourceObjectiveStatus = "unverified-source-field" }
quests[29527] = { id = 29527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Ramparts", description = "Watchkeeper Gargolmar and Vazruden the Herald are in charge of defending these ramparts.\n\nIf you take them out, their forces will be in complete disarray.\n\nSlay them both and bring me proof so the invasion can begin!", sourceObjective = "Slay Watchkeeper Gargolmar, Vazruden the Herald and Vazruden's drake, Nazan. Return Gargolmar's Hand and Nazan's Head to Stone Guard Stok'ton.", progress = "This operation depends on your success, {name}.", completion = "With their leadership dead their forces should be in disarray.\n\nBut there's far more to this than killing a few guards, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29528] = { id = 29528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Ramparts", description = "Hellfire Citadel's entire defensive network relies on the ramparts as a sort of early warning system.\n\nYou need to take out Watchkeeper Gargolmar and Vazruden the Herald. Without them, taking the ramparts will be simple.", sourceObjective = "Slay Watchkeeper Gargolmar, Vazruden the Herald and Vazruden's drake, Nazan. Return Gargolmar's Hand and Nazan's Head to Advance Scout Chadwick.", progress = "Were you successful? We have a lot riding on this operation, {name}.", completion = "I knew I could count on you!\n\nWith their forces in disarray, we can really get this invasion going.", sourceObjectiveStatus = "unverified-source-field" }
quests[29529] = { id = 29529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons in the Citadel", description = "One of our scouts spotted what he thought was an agent of the Burning Legion somewhere in the ramparts. If that is true, then Honor Hold may be in grave danger of a combined assault!\n\nIf you find this fiend in there, kill it on sight.", sourceObjective = "Slay Omor the Unscarred and bring his hoof to Advance Scout Chadwick.", progress = "Did you find any demons in there?", completion = "So it's true. The fel orcs and the Burning Legion are working together in some capacity.", sourceObjectiveStatus = "unverified-source-field" }
quests[29530] = { id = 29530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons in the Citadel", description = "One of our scouts brought back unpleasant news. We've spotted a powerful agent of the Burning Legion in the ramparts!\n\nI need you to kill this demon before he has a chance to relay news of our efforts to his superiors.", sourceObjective = "Kill Omor the Unscarred and bring his hoof to Stone Guard Stok'ton.", progress = "Were you able to dispose of the foul creature?", completion = "Well done. We need the time you've bought us to investigate this link between the fel orcs and the Burning Legion. You very well may have saved hundreds of lives through your actions.", sourceObjectiveStatus = "unverified-source-field" }
quests[29535] = { id = 29535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Them Bleed", description = "The Maker serves the purpose of creating more fel orcs by infusing them with demon blood.\n\nMy superiors believe that we may be able to reverse the process, but we need samples of their blood and The Maker's infusion rod before we can know for sure.", sourceObjective = "Collect 10 Fel Orc Blood Vials and a Fel Infusion Rod for Caza'rez.", progress = "You're back! Even better, you're not dead! Well done. Better than anyone else so far.", completion = "These vials could mean the end of the fel orcs. I hope you understand just how important that is to our campaign here.", sourceObjectiveStatus = "unverified-source-field" }
quests[29536] = { id = 29536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Rage", description = "We know that the fel orcs are growing their forces by infusing orcs with demon blood.\n\nI need you to venture deep inside these unholy halls and find out how that's happening. We can't risk sending an army into this place until we know exactly what we're dealing with.", sourceObjective = "Fully investigate the Blood Furnace and then report back to Caza'rez.", completion = "<You tell Caza'rez everything you saw in the Blood Furnace.>\n\nI see.\n\nIf they can do this to the Mag'har brown orcs, they can do it to us! We must be careful lest they turn all of Thrallmar into those mindless beasts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29537] = { id = 29537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind the Gap", description = "In all of the Blood Furnace, there is one area where our scryers cannot reach despite their efforts.\n\nThis 'gap', as they've been calling it, is fairly large, and must be where Magtheridon is being held captive..\n\nYou must find the source of the interference and dispose of it.", sourceObjective = "Kill Keli'dan the Breaker and return to Caza'rez.", completion = "The interference has gone down, but we still cannot access that area. We will continue to investigate the matter. Thank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[29538] = { id = 29538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Them Bleed", description = "The Maker uses demon blood and a special rod to turn brown and green orcs into red ones. We'd like to see if we can take that blood, mess around with it a bit, and make it turn orcs of all colors into harmless docile lumps. \n\nYou're going to bring me some samples of their blood so we can see. Don't forget to grab that rod!", sourceObjective = "Collect 10 Fel Orc Blood Vials and a Fel Infusion Rod for Gunny.", progress = "You have that blood, darlin'?  Might be kind of important if we asked you to get it, you know?", completion = "Out-frikkin-standing! As of right now, you are my eighth favorite person on the smoldering remains of this sorry planet!", sourceObjectiveStatus = "unverified-source-field" }
quests[29539] = { id = 29539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of Rage", description = "As it turns out, the eggheads back at Honor Hold can't see much into this place. Bunch of lying lazy mages, is what they are.\n\nEither way, we don't really know exactly what's going on in here. So, you're going in to find out!", sourceObjective = "Fully investigate the Blood Furnace and then report back to Gunny.", completion = "<You tell Gunny everything you saw in the Blood Furnace.>\n\nYou brought back some loot for ol' Gunny, right?\n\nNo, no, you're right, clearly I owe you a reward for all your hard work. Not like Gunny didn't arrange all this and send you in there in the first place.", sourceObjectiveStatus = "unverified-source-field" }
quests[29540] = { id = 29540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Breaker", description = "So they've got this big ol' demon stashed away in this place, is what they're telling me. And there's an orc that's in charge of keeping him under wraps.\n\nKilling an orc is killing an orc, am I right? Doesn't matter what he did or what he's doin', orcs are always ripe for the slaughter!", sourceObjective = "Kill Keli'dan the Breaker and return to Gunny.", completion = "Really? You want a reward for killing an orc? As in fame and riches and noble steeds?\n\nBack in my day killing orcs WAS the reward!", sourceObjectiveStatus = "unverified-source-field" }
quests[29542] = { id = 29542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invading the Citadel", sourceObjective = "Speak with Stone Guard Stok'ton in Hellfire Ramparts.", completion = "Shatterskull's not personable by anyone's standards, but he certainly gets the job done. Let's put you to work.", sourceObjectiveStatus = "unverified-source-field" }
quests[29543] = { id = 29543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invading the Citadel", description = "With the Legion to one side and the fel orcs to the other, Honor Hold is going to be overrun in a matter of time if we don't do something about it.\n\nHead west to the Hellfire Ramparts and speak with Advance Scout Chadwick. He's in charge of a covert operation to start an Alliance invasion on the entire citadel.", sourceObjective = "Speak with Advance Scout Chadwick in Hellfire Ramparts.", completion = "That Altumus is certainly a gem, isn't she? But there won't be any of us left alive out here if we aren't successful in our efforts in the ramparts.", sourceObjectiveStatus = "unverified-source-field" }
quests[29563] = { id = 29563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Action", description = "You have to help me! We were sent here to investigate the various parts of the reservoir, but my friends haven't come back yet, and it's been a long time.\n\nThat's why I need you to discover what became of them. Naturalist Bite and Weeder Greenthumb went this way.", sourceObjective = "Discover what happened to Naturalist Bite and Weeder Greenthumb. Then, return to Watcher Jhang.", progress = "Have you discovered anything?", completion = "The loss of life...it pains me.\n\n<Watcher Jhang sighs.>\n\nThank you, {name}. When we are all reunited, the naga won't stand a chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[29564] = { id = 29564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Brother Betrayed", description = "My village was able to escape the naga onslaught at first. We would have all made it to Nagrand had it not been for my brother. He sold our souls for his own freedom.\n\nNow he works here as a slave driver, whipping his own brothers until their backs bleed. Make Mennu pay, {race}.", sourceObjective = "Kill Mennu the Betrayer, then return to Nahuud.", progress = "Is the traitor dead?", completion = "Mennu's death will not fix the broken backs of my family and friends, but it will give them a chance to live the rest of their lives free.", sourceObjectiveStatus = "unverified-source-field" }
quests[29565] = { id = 29565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Matter", description = "From what Nahuud has told me, two mighty creatures, Rokmar the Crackler and Quagmirran, were among the first enslaved by the naga when they arrived. They helped to subjugate many of the native races of Zangarmarsh.\n\nThough it pains me greatly to ask you to do so, you must put them down.", sourceObjective = "Bring The Invader's Claw and The Slave Master's Eye to Watcher Jhang.", progress = "Did you slay them?", completion = "I'm glad that their spirits are now free. I wish we could say the same for the rest of their kind.\n\nThere is still much work to be done, especially elsewhere in Coilfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[29566] = { id = 29566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Checking Up", description = "These marshes are beautiful, wouldn't you agree? That is, except for the naga forces draining the water away.\n\nI sent a small expedition to the Coilfang Reservoir to investigate the naga, and they haven't returned. I'm concerned that something has happened to them.\n\nWould you travel to the Slave Pens underneath Serpent Lake and find Watcher Jhang?", sourceObjective = "Speak with Watcher Jhang in the Slave Pens.", completion = "What're you doing all the way down here? As you can see, it isn't exactly safe!", sourceObjectiveStatus = "unverified-source-field" }
quests[29567] = { id = 29567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalk the Stalker", description = "The spore giants may be attacking my people today, but the marsh walkers have taken more innocent lives than any creature I've ever seen. They are our ancient enemies.\n\nTheir brood mother, the Black Stalker, resides deep within this bog. If you were to destroy her and bring me her brain as proof, I would tell tales of your bravery to my grandchildren.", sourceObjective = "Bring the Brain of the Black Stalker to T'shu.", progress = "You have returned.  Does this mean that The Black Stalker is no more?", completion = "The Black Stalker is dead!  Normally I would not revel in such butchery, but the pain that the great mother and her brood have put my people through over the centuries is unspeakable.\n\nYou have my deepest thanks, brave {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29568] = { id = 29568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Necessary Evil", description = "Hungarfen and Quagmirran used to jointly rule over the spore giants. With Quagmirran gone, the burden rests solely on Hungarfen's tendrils.\n\nWe have no choice but to put the giant down before he can be enslaved and turned into a weapon.", sourceObjective = "Kill Hungarfen, then report back to Naturalist Bite.", progress = "Is the deed done, {name}?", completion = "You've done all of Zangarmarsh a favor this day, {name}. The spore giants may be naturally aggressive, but they're still a vital part of the ecosystem.", sourceObjectiveStatus = "unverified-source-field" }
quests[29570] = { id = 29570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescuing the Expedition", description = "The last members of my expedition are somewhere in here. We're going to need the knowledge they've gathered and their skills if we're to have any chance at defeating the naga.\n\nSee if you can find Earthbinder Rayge and Windcaller Claw, and make sure they're ok.", sourceObjective = "Discover what happened to Earthbinder Rayge and Windcaller Claw. Then, return to Watcher Jhang.", progress = "Were you able to find either of them? Are they ok?", completion = "Soon we'll all be together again, and I owe it all to you!\n\nWe'll bring the naga down before you know it, they don't stand a chance!", sourceObjectiveStatus = "unverified-source-field" }
quests[29571] = { id = 29571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending the Wilds", description = "The Earthen Ring often finds itself working closely with the druids of the Cenarion Circle. Now is one such time.\n\nTravel north to the Underbog and speak with Watcher Jhang. She is in charge of an expedition in the Coilfang Reservoir to stop the naga there and save Zangarmarsh.", sourceObjective = "Speak with Watcher Jhang in the Underbog.", completion = "The Underbog lies precariously on the edge of becoming another part of the Coilfang naga system. You must help us!", sourceObjectiveStatus = "unverified-source-field" }
quests[29573] = { id = 29573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Safety is Job One", description = "It's nearly safe for our men to come in here and take what's rightfully ours. The real danger now is Shaffar's personal army that he has crawling all over this place.\n\nI need you to take care of his forces for me while I regain my strength.", sourceObjective = "Kill 10 Ethereal Crypt Raiders, 5 Ethereal Sorcerers, 5 Nexus Stalkers, and 5 Ethereal Spellbinders, then return to Artificer Morphalius.", progress = "Done already? You {race} continue to fascinate me.", completion = "Splendid! Haramad will be delighted to hear the good news! All of this ripe for his taking!", sourceObjectiveStatus = "unverified-source-field" }
quests[29574] = { id = 29574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intriguing Specimens", description = "There is a creature not far inside these halls called Pandemonius who is able to twist void energies to sustain and empower itself.\n\nA bit further in lies Tavarok, a being that takes those same void energies and converts them into a crystalline structure stronger than any I've ever seen!\n\nI absolutely must obtain samples for further study.", sourceObjective = "Bring Pandemonius' Essence and Tavarok's Heart to Mamdy the \"Ologist\".", progress = "If you don't have what I'm looking for, stop wasting my time.", completion = "These samples are absolutely fascinating. They'll work very nicely.", sourceObjectiveStatus = "unverified-source-field" }
quests[29575] = { id = 29575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercutting the Competition", description = "With his ward in place and his forces ready, Nexus-Prince Shaffar has been able to pillage this place for all it's worth without so much as an ounce of trouble.\n\nUnsurprisingly, Nexus-Prince Haramad isn't pleased by this, and has placed a hefty bounty on Shaffar's head.", sourceObjective = "Bring Shaffar's Wrappings to Artificer Morphalius.", progress = "Were you interested in the bounty on Shaffar's head?", completion = "I didn't honestly think a {race} would be able to defeat a Nexus-Prince. You've surprised me, and you've earned the handsome reward you were promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[29582] = { id = 29582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grek's Crazy Night", description = "Grek had bad night last night.\n\nShiny mummy man came into Grek's house and told Grek that he had to go to Mana Tombs in Auchindoun. But Grek still trying to read wanted poster!\n\n<Grek's face lights up.>\n\nGrek knows! You go find shiny mummy man and tell him Grek sent you. It perfect plan!", sourceObjective = "Speak with Artificer Morphalius in the Mana Tombs in Auchindoun.", completion = "That meathead send you instead?\n\n<Artificer Morphalius looks you over.>\n\nI suppose you'll have to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[29583] = { id = 29583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eckert the Mad", description = "I'm a skilled engineer, a brilliant inventor, the heart of any party, and the best dancer Azeroth has ever seen.\n\nDo they call me those things? No.\n\nBut you have one run-in with a ethereal and all of the sudden everyone and their mother calls you \"the mad\".\n\nI saw one right here just yesterday, I swear it! He said if I followed him to the Mana Tombs in Auchindoun there would be vast treasure and ancient knowledge awaiting me!", sourceObjective = "Speak with Artificer Morphalius in the Mana Tombs in Auchindoun.", completion = "I was truly hoping that the gnome I sought out would be the one to answer my call.\n\n<Artificer Morphalius looks you over.>\n\nI suppose you'll do.", sourceObjectiveStatus = "unverified-source-field" }
quests[29590] = { id = 29590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dead Watcher", description = "A terrifying otherworldly being haunts both the spirit and physical worlds. We call it Shirrak.\n\nIt can only be harmed in your realm. Please help rid us of this nightmare.", sourceObjective = "Kill Shirrak the Dead Watcher, then return to the Draenei Spirit.", completion = "Perhaps now we can finally be at peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[29591] = { id = 29591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raging Spirits", description = "The Auchenai have turned their backs on everything we used to stand for. They've taken to raising the dead as unholy minions!\n\nThis cannot stand. Put the spirits back to rest, and massacre those responsible for raising them into undeath.", sourceObjective = "Slay 5 Angered Skeletons, 5 Raging Skeletons, and 3 Auchenai Necromancers, then return to the Tormented Soulpriest in Auchenai Crypts.", completion = "The dead belong in the spirit realm. Just as you belong in this one.", sourceObjectiveStatus = "unverified-source-field" }
quests[29593] = { id = 29593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting Them Where It Hurts", description = "The fel orcs have stockpiled many of their supplies here.\n\nStealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, {class}?", sourceObjective = "Steal 3 piles of Hellfire Supplies, then return to Stone Guard Stok'ton in Hellfire Ramparts.", progress = "How many piles were you able to take?", completion = "Well done! The long term effects of this attack will be far worse than slaying a few orcs could ever be.", sourceObjectiveStatus = "unverified-source-field" }
quests[29594] = { id = 29594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting Them Where It Hurts", description = "The fel orcs have stockpiled many of their supplies here.\n\nStealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, {class}?", sourceObjective = "Steal 3 piles of Hellfire Supplies, then return to Advance Scout Chadwick in Hellfire Ramparts.", progress = "How many piles were you able to take?", completion = "Well done! The long term effects of this attack will be far worse than slaying a few orcs could ever be.", sourceObjectiveStatus = "unverified-source-field" }
quests[29595] = { id = 29595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything Will Be Alright", description = "You've had quite an adventure, {name}. And before you've even set foot inside of the Auchenai Crypts.\n\nI am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar's vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts.\n\nWhat I ask is simple. Enter the Auchenai Crypts and speak with the Draenei Spirit there. You must destroy Exarch Maladaar.", sourceObjective = "Greatfather Aldrimus standing outside the Auchenai Crypts of Auchindoun has asked that you enter the Auchenai Crypts and speak with the Draenei Spirit.", completion = "Welcome to the Auchenai Crypts, {name}, where our two worlds meet.", sourceObjectiveStatus = "unverified-source-field" }
quests[29596] = { id = 29596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Exarch", description = "Exarch Maladaar performs his unholy work in the deepest part of the crypts. He poses a threat to both of our worlds if he is not stopped.\n\nYou must slay him for the benefit of us all, dead and alive.", sourceObjective = "Kill Exarch Maladaar and return to the Draenei Spirit inside the Auchenai Crypts.", completion = "You have done our realm a great service. You will not be forgotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[29598] = { id = 29598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taretha's Diversion", description = "It was Taretha who created the original diversion at Durnholde, allowing Thrall to escape.\n\nNow the Infinite have captured Taretha. The diversion will not happen without our involvement. You must use the incendiary devices that I give you and burn down the internment lodges.", sourceObjective = "Travel to Durnholde Keep and set 5 incendiary charges at the barrels located inside each of the internment lodges using the Pack of Incendiary Bombs given to you by Erozion.\n\nSpeak to Thrall in the basement prison of Durnholde Keep when you have the Internment Lodges Set Ablaze.", progress = "Who are you?", completion = "You are friends of Taretha? So this is her new plan? Very well then...", sourceObjectiveStatus = "unverified-source-field" }
quests[29599] = { id = 29599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Durnholde", description = "I have plans for my people, stranger.\n\nOne day, they shall overthrow their oppressors and rise as one. They will break free from the bonds that hold them and from that uprising shall be born the orcish Horde.\n\nWe will leave when you are ready.", sourceObjective = "When you are ready to proceed, let Thrall know. Follow Thrall out of Durnholde Keep and help him free Taretha and fulfill his destiny.\n\nSpeak with Erozion in Old Hillsbrad should you complete this task.", completion = "You have done a great thing, {name}. Alas, the young warchief's memory of these events must be as they originally were...", sourceObjectiveStatus = "unverified-source-field" }
quests[29605] = { id = 29605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Against Brother", description = "The Sethekk departed Skettis when Auchindoun exploded.\n\nMy brother, Syth, was one of their leaders and told us we had to go into the ruins and face our god.\n\nIn time, Syth had me cast out of the Halls for doubting them, but he refused to let me take our sister Lakka. Will you help me rescue her?", sourceObjective = "Free Lakka from captivity. Return to Isfar inside the Sethekk Halls when you've completed the rescue.", completion = "Knowing that Lakka is free means I can cut the rest of my ties to the Sethekk.\n\nPart of me will never forgive myself for Syth's death, but it had to be done. When I reach Skettis, I will perform the death rites for him.", sourceObjectiveStatus = "unverified-source-field" }
quests[29606] = { id = 29606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terokk's Legacy", description = "Terokk, hero of the Arakkoa, mysteriously vanished one day, leaving only his mask and spear behind.\n\nDarkweaver Syth still holds his mask and Talon King Ikiss guards his spear.\n\nIt would mean a great deal to my people if these items were returned to us.", sourceObjective = "Bring Terokk's Mask and Terokk's Quill to Isfar inside the Sethekk Halls.", progress = "The relics of Terokk have been absent from Skettis for too long. Were you able to recover them from the Sethekk?", completion = "I may never truly be forgiven for my role in the crimes of the Sethekk, but perhaps by restoring the relics of Terokk to my people, I can begin to redeem myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[29607] = { id = 29607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of Desire", description = "I have a buyer who is interested in the eyes of the Cobalt Serpents that have taken up residence here.\n\nIf you were to bring me some of these rare gems, I would cut you a portion of the profits.\n\nDo we have a deal?", sourceObjective = "Dealer Vijad inside the Sethekk Halls wants you to bring him 3 Cobalt Eyes.", progress = "Did you bring the eyes?", completion = "These are marvelous. Well done!\n\nHere's your cut, as promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[29608] = { id = 29608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allies in Dalaran", description = "Welcome to Northrend, {name}. I have been asked to arrange travel for you to Dalaran so that you can meet with our allies there.\n\nRide the gryphon to Dalaran and once you land, make your way to our inn there, A Hero's Welcome. Find Isirami Fairwind and speak with her immediately.\n\nShe can help you bind your hearthstone to the city so you can use the Silver Enclave's portal to travel back to Stormwind quickly.", sourceObjective = "Accept a gryphon ride to Dalaran and speak with Isirami Fairwind at A Hero's Welcome.", completion = "Welcome to Dalaran! This inn is part of the Silver Enclave, the headquarters of the official Alliance presence in our city.\n\nDon't forget to bind your hearthstone here for easy travel to the city and access to the portal to Stormwind next door.", sourceObjectiveStatus = "unverified-source-field" }
quests[29609] = { id = 29609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends in Dalaran", description = "Welcome to Northrend. I have been asked to arrange travel for you to Dalaran so that you can meet our friends in the city.\n\nSpeak with me and accept a ride to Dalaran. Once you land, make your way to The Filthy Animal.\n\nMake contact with Uda the Beast immediately.\n\nShe can help you bind your hearthstone to the city so you can use the portal in Sunreaver's Sanctuary to travel back to Orgrimmar quickly.", sourceObjective = "Accept a ride to Dalaran from the flight master and speak with Uda the Beast at The Filthy Animal.", completion = "I've been expecting you! This inn is part of Sunreaver's Sanctuary, the Horde's enclave in Dalaran.\n\nDon't forget to bind your hearthstone here for easy travel to the city and access to the portal to Orgrimmar, out by the fountain.", sourceObjectiveStatus = "unverified-source-field" }
quests[29613] = { id = 29613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Fate", description = "Warlord Kalithresh is in charge of the entire Steamvault operation.\n\nI need you to kill him, {name}. The naga have left us with no option but violence.\n\nShow him no mercy.", sourceObjective = "Kill Warlord Kalithresh and return to Watcher Jhang inside the Steamvault.", completion = "I wish it had not come to this, but the naga refused all attempts to negotiate.", sourceObjectiveStatus = "unverified-source-field" }
quests[29614] = { id = 29614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containment is Key", description = "The naga are working with leper gnomes to spread a horrific disease across Zangarmarsh. It's already spread throughout the Steamvault.\n\nClear out anything that's been contaminated and bring me the central gear from Mekgineer Steamrigger, quickly!", sourceObjective = "Kill 3 Bog Overlords, 6 Coilfang Lepers, and obtain an Irradiated Gear from Mekgineer Steamrigger, then return to Naturalist Bite inside the Steamvault.", progress = "Be as thorough as possible. The fate of Zangarmarsh depends on it.", completion = "I'm glad we were able to contain this before it spread across all of Zangarmarsh or further. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29615] = { id = 29615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windcaller Claw and the Water Thief", description = "The Steamvault is the heart of the naga's efforts to pump the water out of Zangarmarsh, and Hydromancer Thespia personally oversees those efforts.\n\nTaking her out would seriously hinder their operation.", sourceObjective = "Kill Hydromancer Thespia and return to Windcaller Claw inside the Steamvault.", progress = "Did you dispatch of the water thief?", completion = "Perhaps now we can restore all of the desperately needed water to the land.", sourceObjectiveStatus = "unverified-source-field" }
quests[29616] = { id = 29616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Steamvault", description = "We have not as of yet been able to stop the naga in the Steamvault, where most of their pumping infrastructure is located.\n\nThankfully, the expedition I sent there is hard at work trying to change that fact. Will you travel to the Steamvault and offer Watcher Jhang and her crew your aid?", sourceObjective = "Speak with Watcher Jhang in the Steamvault.", completion = "Thank the stars you're here. We need your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[29640] = { id = 29640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Spy To'gun", description = "The Shadow Council has already killed most of our spies, but To'gun was foolish enough to escape only to go back in!\n\nYou must find him. He may be reckless, but we need to find out what he knows.", sourceObjective = "Locate Spy To'gun in the Shadow Labyrinth of Auchindoun.", completion = "Do you think you could help me get out of this cage?  It's a bit cramped.", sourceObjectiveStatus = "unverified-source-field" }
quests[29641] = { id = 29641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul Devices", description = "They've been torturing me, trying to get me to tell them everything that I know.\n\nThey fed the others to Hellmaw, and I was to be next. But I told them nothing!\n\nThey're using special devices to make their summoning more powerful. You must steal these devices!", sourceObjective = "Steal 5 Soul Devices and deliver them to Spy Grik'tha inside the Shadow Labyrinth of Auchindoun.", progress = "Were you able to find To'gun?", completion = "So, these are the soul devices that the Shadow Council were using to enhance their summoning power?  Intriguing.", sourceObjectiveStatus = "unverified-source-field" }
quests[29642] = { id = 29642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Auchindoun", description = "I have spies within Auchindoun and they have been sending me disturbing reports.  That place has been nothing but trouble ever since it exploded a couple of years ago.\n\nSomething in there has gone horribly wrong - again - and the Shadow Council is now on a war footing.  Though the reports were lacking on details, their preparations appear to be directed inward.\n\nYou must make your way to the Shadow Labyrinth.  My field commander, Mahfuun, will fill you in on what needs to be done.", sourceObjective = "Report to Field Commander Mahfuun inside the Shadow Labyrinth at Auchindoun in Terokkar Forest.", completion = "It's about time that you arrived.\n\nMehlisah said that she would be sending help days ago.  And we've been fighting in here longer than that!", sourceObjectiveStatus = "unverified-source-field" }
quests[29643] = { id = 29643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Codex of Blood", description = "Two years ago the Shadow Council summoned forth a being that shattered Auchindoun in its wake.\n\nRead the Codex of Blood to find out what happened. Be warned, Grandmaster Vorpil guards it with his life.", sourceObjective = "Read from the Codex of Blood in the Shadow Labyrinth of Auchindoun.", completion = "Opening the magically-suspended tome, a sense of dread overwhelms you.\n\nSomething is most definitely wrong here!", sourceObjectiveStatus = "unverified-source-field" }
quests[29644] = { id = 29644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Heart of the Labyrinth", description = "The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago.\n\nKnown only as Murmur, it threatens to overrun the Shadow Council and break free into the outside world!", sourceObjective = "Destroy Murmur and inform Field Commander Mahfuun inside the Shadow Labyrinth of Auchindoun.", completion = "I cringe to think what would have happened had Murmur escaped to the outside world.\n\nThank you, brave hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[29645] = { id = 29645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambassador Hellmaw", description = "When the Cabal found our spies, they fed them to Ambassador Hellmaw one by one.\n\nOur men deserve justice. Slay the ritualists binding him, then dispose of Hellmaw.\n\nIt is a most deserving fate.", sourceObjective = "Kill 18 Cabal Ritualists and Ambassador Hellmaw, then return to Field Commander Mahfuun inside the Shadow Labyrinth of Auchindoun.", completion = "It won't bring anyone back, but at least justice has been done.", sourceObjectiveStatus = "unverified-source-field" }
quests[29649] = { id = 29649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Save a Life", description = "Gunny is dying from a powerful curse, {name}.\n\nGrand Warlock Nethekurse augments his power with a pair of mystical braziers. If you bring me an ember from that brazier, perhaps it can counteract the dark magic?", sourceObjective = "Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel wants you to bring him a Fel Ember.", progress = "Did you bring the ember? We don't have much time!", completion = "He was a good soldier.", sourceObjectiveStatus = "unverified-source-field" }
quests[29650] = { id = 29650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Ember", description = "Caza'rez is dying a coward's death.\n\nGrand Warlock Netherkurse placed a terrible curse upon him. Perhaps if you were to bring me one of the embers from his braziers, we could use it to counteract the magic before it's too late?", sourceObjective = "Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel wants you to bring him a Fel Ember.", progress = "Did you bring the ember? Caza'rez deserves a warrior's death.", completion = "I will sing many songs of his glories.", sourceObjectiveStatus = "unverified-source-field" }
quests[29651] = { id = 29651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Dying", description = "Their elite warriors are ruthless...so... powerful.\n\n<Caza'rez spits up blood.>\n\nYou have to kill them...or we will never defeat Kargath...", sourceObjective = "Caza'rez inside the Shattered Halls of Hellfire Citadel wants you to kill 4 Shattered Hand Legionnaires, 2 Shattered Hand Centurions, and 2 Shattered Hand Champions.", progress = "Are they dead, {class}?", completion = "Caza'rez...is no more.", sourceObjectiveStatus = "unverified-source-field" }
quests[29652] = { id = 29652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Last Favor", description = "Ol' Gunny doesn't have much longer...\n\nDo me one last favor, and kill the biggest, meanest fel orcs ye can find.\n\nFor old times' sake, aye?", sourceObjective = "Gunny inside the Shattered Halls of Hellfire Citadel wants you to kill 4 Shattered Hand Legionnaires, 2 Shattered Hand Centurions, and 2 Shattered Hand Champions.", progress = "Did ye kill 'em?", completion = "If only we could have saved him.", sourceObjectiveStatus = "unverified-source-field" }
quests[29653] = { id = 29653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Will of the Warchief", description = "Kargath was once one of the Horde's greatest heroes.\n\nHe now wears the false mantle of Warchief. Bring me his namesake weapon so that we can remember the champion he once was, rather than the monster he's become.", sourceObjective = "Bring Warchief Kargath's Fist to Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", progress = "Have you proof of Kargath Bladefist's defeat?", completion = "We should not forget the orc Kargath once was, nor the lessons to be learned from his downfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[29654] = { id = 29654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Tide", description = "There is only one true way to end the fel orc threat to Honor Hold and the Alliance.\n\nTheir Warchief must be slain.\n\nBring me his namesake weapon, so that we can always remember his death.", sourceObjective = "Bring Warchief Kargath's Fist to Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", progress = "Have you returned with proof of 'Warchief' Kargath Bladefist's demise?", completion = "We have struck a major blow against the enemy with your help.\n\nHonor Hold is far safer than it's been in years.", sourceObjectiveStatus = "unverified-source-field" }
quests[29655] = { id = 29655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Very Special Cloth", description = "Warbringer O'mrogg has killed more brave soldiers than any enemy I've ever encountered. He is ruthless, cunning, and extremely powerful.\n\nTake him down and bring me his warcloth so that we may fashion it into a banner and show them the fury of the Horde!", sourceObjective = "Kill Warbringer O'mrogg and bring his warcloth to Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", progress = "Did you bring me the cloth?", completion = "Well done. This will show those blood crazed monsters what they're up against.", sourceObjectiveStatus = "unverified-source-field" }
quests[29656] = { id = 29656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "O'mrogg's Warcloth", description = "Stormwind wants to see proof of our successes in the war effort.\n\nRather than showing him body bags, I thought we'd present him the warcloth of O'mrogg, Kargath's fiercest warrior. Think you can handle him?", sourceObjective = "Kill Warbringer O'mrogg and bring his warcloth to Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", progress = "Did you bring me the cloth?", completion = "My superiors will be very pleased to see this. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29657] = { id = 29657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "With Great Power, Comes Great Responsibility", description = "<A voice like the sound of light bells rings in your head.>\n\nThe Mechanar employs my race's technology to create manacells, objects which provide great amounts of power.\n\nI need you to eliminate Mechano-Lord Capacitus so that Kael'thas' forces cannot harvest that power.", sourceObjective = "A'dal has asked you to slay Mechano-Lord Capacitus in the Mechanar of Tempest Keep.", completion = "You have done well, {name}. But more work remains to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[29658] = { id = 29658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Calculator", description = "<A gentle wind caresses your face.>\n\nOne more task yet remains.\n\nPathaleon the Calculator oversees many of his master's operations. He is personally responsible for much of the recent torment that has plagued this world.\n\nI ask that you eliminate him.", sourceObjective = "A'dal has asked you to slay Pathaleon the Calculator in the Mechanar of Tempest Keep.", completion = "You have my gratitude, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29659] = { id = 29659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Treasure", description = "I sense that one of my kind's artifacts has been taken and stashed away in the Cache of the Legion.\n\nWe cannot give them time to discover its power. If you would kill the Gatewatchers and retrieve it for me, I would be most grateful.", sourceObjective = "Retrieve the Blinding Fury for A'dal from the Cache of the Legion in the Mechanar of Tempest Keep.", sourceObjectiveStatus = "unverified-source-field" }
quests[29660] = { id = 29660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Botanica", description = "Kael'thas' forces in the Botanica were unsuccessful in handling the numerous creatures contained within. We must take action to right their wrongs.\n\nThe first step is to eliminate their forces so that they cannot cause further problems.", sourceObjective = "A'dal wants you to kill Commander Sarannis, High Botanist Freywinn, and Thorngrin the Tender inside the Botanica of Tempest Keep.", completion = "They were going to die to the creatures contained here soon even without our interference. It is for the greater good.", sourceObjectiveStatus = "unverified-source-field" }
quests[29667] = { id = 29667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Herd", description = "It seems that Kael'thas' forces have twisted the Botanica's specimens beyond saving. I do not want to see them unleashed upon Outland as so many others have.\n\nThere is one, Laj, who I would like to examine. He is different somehow. Perhaps we can learn from him.", sourceObjective = "A'dal has asked you to kill 6 Mutate Fleshlashers, 6 Mutate Fear-shriekers, 6 Mutate Horrors, and to obtain a Rapidly Evolving Frond from Laj in the Botanica of Tempest Keep.", progress = "I see you have obtained the frond. Very good.", completion = "You have done well thus far, {name}. However, there is still one more task I must ask that you complete.", sourceObjectiveStatus = "unverified-source-field" }
quests[29669] = { id = 29669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Somber Task", description = "I must now ask you to complete a most somber task.\n\nWarp Splinter used to act as guardian to all of the Botanica. He is now impure, and must be taken down.", sourceObjective = "A'dal has asked you to slay Warp Splinter in the Botanica of Tempest Keep.", completion = "He was a noble guardian in life. His presence will be missed.", sourceObjectiveStatus = "unverified-source-field" }
quests[29674] = { id = 29674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbound Darkness", description = "<The sound of chimes enters your head, but it is distressed.>\n\nWe imprisoned the most dangerous beings we came across in our travels.\n\nZereketh is a powerful void lord. If he escapes into Netherstorm, he will feed off of the abundant void energy.", sourceObjective = "A'dal has asked you to slay Zereketh the Unbound in the Arcatraz of Tempest Keep.", completion = "Creatures of the void are naturally chaotic. They are a necessary part of the universe, but they must be kept in check by the Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[29675] = { id = 29675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hey There Dalliah", description = "Two powerful agents of the Burning Legion, Wrath-Scryer Soccothrates and Dalliah the Doomsayer, have begun rallying the demons on board together into a small army.\n\nYou cannot let their forces grow any larger, or the Arcatraz may soon become yet another Legion stronghold.", sourceObjective = "A'dal has asked you to kill Wrath-Scryer Soccothrates and Dalliah the Doomsayer in the Arcatraz of Tempest Keep.", completion = "The Legion seeks only to consume. They hold no regard for the balance.", sourceObjectiveStatus = "unverified-source-field" }
quests[29681] = { id = 29681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maximum Security Breakout", description = "Harbinger Skyriss is the heart of the problem in the Arcatraz.\n\nHe corrupted Warden Mellichar and made him release many of the prisoners. It is only a matter of time before the Harbinger himself is let loose.\n\n{name}, you cannot let a servant of the Old Gods live!", sourceObjective = "A'dal has asked you to slay Harbinger Skyriss in the Arcatraz of Tempest Keep.", completion = "Thank you, {name}. Your actions this day have prevented countless tragedies.", sourceObjectiveStatus = "unverified-source-field" }
quests[29682] = { id = 29682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magisters' Terrace", description = "We recently sent in an expeditionary force to the Magisters' Terrace to stop the Legion forces there.\n\nHowever, we haven't heard from them since, and I fear the worst.\n\nWill you go there and try to find Exarch Larethor? He's in charge of the expedition.", sourceObjective = "Captain Theris Dawnhearth wants you to find Exarch Larethor inside the Magisters' Terrace.", completion = "Dawnhearth thought we were dead? Hah!\n\nI haven't sent a report because we haven't made any progress past this point.\n\nPerhaps you can help us change that?", sourceObjectiveStatus = "unverified-source-field" }
quests[29684] = { id = 29684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Severed Communications", description = "We've had a contact embedded in Magisters' Terrace gathering intelligence for us for some time now, but we've lost contact with him.\n\nThe information he was collecting is vital to our mission.", sourceObjective = "Exarch Larethor inside the Magisters' Terrace wants you to find Tyrith, a blood elf spy.", completion = "...Come closer, {race}... Listen carefully to my words....", sourceObjectiveStatus = "unverified-source-field" }
quests[29685] = { id = 29685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard to Kill", description = "As you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends.\n\nKael'thas has risen from the ashes of defeat and once more leads them in their efforts. He must be stopped.", sourceObjective = "Kalecgos has asked you to defeat Kael'thas in Magisters' Terrace. You are to take Kael's head and report back to Larethor inside the Magisters' Terrace.", progress = "Well, {class}, I must admit, I wasn't sure I'd see you again.", completion = "<Larethor listens intently as you explain your deeds in Magisters' Terrace.>\n\nTyrith will be missed - good man, that one. Thanks to you though, his death wasn't in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[29686] = { id = 29686, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Radical Notion", description = "We cannot afford to lose this war. I'd like to empower our sentries so that brave men and women don't have to die.\n\nThe Legion has gotten a hold of a powerful elemental being. Its essence could be just what we need.", sourceObjective = "Exarch Larethor in the Magisters' Terrace wants you to kill Vexallus and obtain its essence.", progress = "Were you able to get your hands on its essence?", completion = "Excellent! I can't wait to present this project to my superiors!", sourceObjectiveStatus = "unverified-source-field" }
quests[29687] = { id = 29687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Associations", description = "The Legion and Kael'thas' forces are becoming increasingly intertwined. This concerns me very deeply.\n\nFrom what we can gather Selin Fireheart and Priestess Delrissa work closely together to unite the two armies. You need to stop them.", sourceObjective = "Exarch Larethor in the Magisters' Terrace wants you to kill Selin Fireheart and Priestess Delrissa.", completion = "Well done, soldier. One step at a time.", sourceObjectiveStatus = "unverified-source-field" }
quests[29688] = { id = 29688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advancing the Campaign", description = "I mostly listen, {class}. I listen so that the Warchief doesn't have to.\n\nI've heard of the status of our campaign against the Hellfire Citadel. It is time to take the Shattered Halls, seat of power for the fel orcs.\n\nGo speak with Stone Guard Stok'ton, he's in charge there.", sourceObjective = "Shadow Hunter Ty'jin has asked you to speak with Stone Guard Stok'ton inside the Shattered Halls of Hellfire Citadel.", completion = "Keep your head down, or it's likely to end up on the wrong end of an arrow.", sourceObjectiveStatus = "unverified-source-field" }
quests[29689] = { id = 29689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advancing the Campaign", description = "The time has come to lay the final blow against the fel orcs.\n\nAdvance Scout Chadwick awaits your presence inside the Shattered Halls of Hellfire Citadel. Make haste, their forces could strike against Honor Hold at any moment!", sourceObjective = "Force Commander Danath Trollbane has asked you to speak with Advance Scout Chadwick inside the Shattered Halls of Hellfire Citadel.", completion = "Be quiet! We'll surely be overwhelmed if they notice us now.", sourceObjectiveStatus = "unverified-source-field" }
quests[29691] = { id = 29691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me A Shrubbery!", description = "My people use sanguine hibiscus for a number of purposes.\n\nIt grows naturally only in the Underbog, and many of the bog's denizens have taken a liking to it.\n\nIf you could bring me some, I would be very grateful.", sourceObjective = "Collect 5 Sanguine Hibiscus and return them to T'shu in the Underbog.", progress = "Were you able to gather any hibiscus?", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?", sourceObjectiveStatus = "unverified-source-field" }
quests[29692] = { id = 29692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Me Another Shrubbery!", progress = "We can still use more sanguine hibiscus. We're always struggling to find more.\n\nBring them to me in bunches of five and I will be most grateful.", completion = "These will do nicely, but we can always use more.  Perhaps you will find yourself in the Underbog again soon?" }
quests[29734] = { id = 29734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deepforge the Elder" }
quests[29735] = { id = 29735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonebrand the Elder" }
quests[29736] = { id = 29736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkfeather the Elder" }
quests[29737] = { id = 29737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firebeard the Elder" }
quests[29738] = { id = 29738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonlance the Elder" }
quests[29739] = { id = 29739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windsong the Elder" }
quests[29740] = { id = 29740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evershade the Elder" }
quests[29741] = { id = 29741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sekhemi the Elder" }
quests[29742] = { id = 29742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menkhaf the Elder" }
quests[29760] = { id = 29760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pit Fighter", description = "There must be more to being a master pit fighter than this...\n\nPerhaps Korgol Crushskull who runs the Darkmoon Deathmatch at the Faire will know.", sourceObjective = "Speak with Korgol Crushskull at the Darkmoon Faire.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[29761] = { id = 29761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master Pit Fighter" }
quests[29763] = { id = 29763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing Their Thunder", description = "The vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we're doomed - plain and simple.\n\nThere's one they esteem though, goes by the name of Ingvar. Bring him down and you'll deal a mighty blow to their spirit.", sourceObjective = "Defender Mordun has asked you to acquire the head of Ingvar the Plunderer.", progress = "Good to see you're well, {name}.\n\nWe've had about as many casualties as we can handle.", completion = "Outstanding!\n\nThis could be the turn of luck we've all been hoping for.", sourceObjectiveStatus = "unverified-source-field" }
quests[29764] = { id = 29764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarmament", description = "Take it from me, <lad/lass>, them vrykul weapons be downright nasty! Deceptively well-balanced, wickedly sharp - just plain deadly.\n\nI need you to pilfer some o' them weapons before they're used on us!", sourceObjective = "Defender Mordun wants you to steal 5 Vrykul Weapons", progress = "You pinch a load a' them vrykul axes?", completion = "<Mordun whistles.>\n\nWill ya just look at 'em? Incredible.\n\nI half expected these neanderthals to be swingin' around clubs and throwin' rock.\n\nNo such luck...", sourceObjectiveStatus = "unverified-source-field" }
quests[29801] = { id = 29801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Your Worth", description = "Hello, {name}! You've earned a reputation among the flight as having - shall we say - 'nimble fingers.'\n\nWe need someone of your skills for a matter of utmost delicacy. Before I reveal more, we need to know you're the right <man/woman> for the job.\n\nWhen the course of battle takes you to the Eye of Eternity, I need you to pickpocket Hagara the Stormbinder to retrieve a cryptomancer's decoder ring. Are you up to the task?", sourceObjective = "Pickpocket a cryptomancer's decoder ring from Hagara the Stormbinder at the Eye of Eternity within the Dragon Soul raid encounter.", sourceObjectiveStatus = "unverified-source-field" }
quests[29803] = { id = 29803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ears of the Lich King", description = "Prince Keleseth acts as Arthas' eyes and ears in the Fjord.\n\nI don't like that one bit!\n\nGo and give him a round o' pain. You'll be doing the world a favor by doing so.", sourceObjective = "Defender Mordun inside Utgarde Keep wants you to slay Prince Keleseth.", completion = "I bet the pale whelp felt that!\n\nThat's one more step towards yer judgment day, Arthas!", sourceObjectiveStatus = "unverified-source-field" }
quests[29807] = { id = 29807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Traitor King", description = "Anub'arak, the traitor king, makes his home in the once proud Kingdom of Azjol-Nerub.\n\nHe has twisted and perverted our homeland into the wretched squalor it is today. He rules over an army of undead nerubians who have pledged themselves to serving the Lich King.\n\nBring an end to his reign.", sourceObjective = "Reclaimer A'zak in Azjol-Nerub has tasked you with defeating Anub'arak. You are to return to A'zak with Anub'arak's Broken Husk.", progress = "Is it done, {class}? Has the traitor king finally met his end?", completion = "<A fierce glow emanantes from all of Azak's eyes as he stares at the husk.>\n\nIt is DONE!\n\nYour name shall be recorded in the extensive history of our people, {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29808] = { id = 29808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget the Eggs!", description = "Throughout Azjol-Nerub, the scourged nerubians carefully nurture eggs that will soon hatch, providing them nerubian young to slaughter and raise.\n\nThe eggs have been tainted with foul magics. Our only recourse is to dispose of them.", sourceObjective = "Reclaimer A'zak in Azjol-Nerub wants you to destroy 6 Nerubian Scourge Eggs.", completion = "Do not worry, {race}.\n\nThe eggs they found were but a fraction of our hidden stores within Azjol-Nerub.\n\nOur mighty kingdom shall be reborn.", sourceObjectiveStatus = "unverified-source-field" }
quests[29811] = { id = 29811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gatewatcher's Talisman", description = "Krik'thir, guardian of the gates to Azjol-Nerub, was not a traitor.\n\nHe fell in the War of the Spider defending our home from the Scourge.\n\nAs per his station, he was in possession of the key to the hidden empire. I'd like you to retrieve it so it may be returned to its people.", sourceObjective = "Reclaimer A'zak in Azjol-Nerub wants you to retrieve the Gatewatcher's Talisman from Krik'thir the Gatewatcher.", progress = "Has Krik'thir's spirit been released from the curse of undeath? What of the talisman?", completion = "Just as I suspected.\n\nMost of the empire has remained closed off since Krik'thir's final stand. Perhaps my people have already secured the depths and merely await release? Perhaps the faceless ones fester behind closed doors.\n\nOnly time will tell. The exposed upper reaches of Azjol-Nerub must first be cleansed of Arthas' taint.", sourceObjectiveStatus = "unverified-source-field" }
quests[29820] = { id = 29820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Nexus", description = "I sent Warmage Kaitlyn into the Nexus to investigate the chaos that is Malygos' domain, but she hasn't reported back in days.\n\nWould you mind going there and lending her aid? I'm certain she could use help if she hasn't been eaten by dragons.", sourceObjective = "Archmage Berinand has asked you to speak with Warmage Kaitlyn in the Nexus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29825] = { id = 29825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pupil No More", description = "I once called Elder Nadox my teacher.\n\nThat changed forever when I was forced to watch him mercilessly slaughter my friends and family as a servant of the damned.\n\nFind him within the depths and make him pay for his crimes, {race}.", sourceObjective = "Seer Ixit in Ahn'Kahet has tasked you with the assassination of Elder Nadox.", progress = "Is the mighty Nadox dead for good?", completion = "With Nadox gone, I hope to take his place as a leader of my people.\n\nThe Empire of Azjol-Nerub is destined for greatness, {race}...", sourceObjectiveStatus = "unverified-source-field" }
quests[29826] = { id = 29826, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Ahn'Kahet", description = "Prince Taldaram and his army of Scourge use the same wards we once used to hide our empire to keep themselves safe from the native denizens of the icy depths.\n\nDeactivate the wards and slaughter the Scourge guarding them. My forces will help the natives slaughter the rest.", sourceObjective = "Seer Ixit in Ahn'Kahet wants you to kill 3 Eyes of Taldaram, a Bonegrinder, and Prince Taldaram.", progress = "Much work remains to be done in Ahn'Kahet, even long after the Scourge are defeated.", completion = "Excellent.\n\n<You heard a series of clicking sounds.>\n\nNow to vanquish our other foe.", sourceObjectiveStatus = "unverified-source-field" }
quests[29828] = { id = 29828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Scourge Dred", description = "One of the fleeing Drakkari trolls told me of a great raptor king, Dred, that was immune to the plague.\n\nIf you could find King Dred and bring me one of his teeth, perhaps I could fashion it into a weapon.", sourceObjective = "Kurzel inside Drak'Tharon Keep wants you to slay King Dred and bring her his tooth.", progress = "Does the great beast exist?", completion = "<Kurzel's eyes open wide.>\n\nWow! That's enormous!", sourceObjectiveStatus = "unverified-source-field" }
quests[29829] = { id = 29829, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discretion is Key", description = "Listen to me, {race}.\n\nIt's just been brought to my attention that there's been an incident at the Violet Hold. It would appear that the blues are launching a full scale invasion of Dalaran!\n\nI need you to get to the prison and speak with Lieutenant Sinclari at once. She'll give you the details.\n\nThat is not all. I need this handled with utmost discretion. We mustn't alarm the citizens of Dalaran if it can possibly be avoided. Do I make myself clear?\n\nVery well. Now, go!", sourceObjective = "Rhonin wants you to go to the Violet Hold in Dalaran and speak with Lieutenant Sinclari.", completion = "Not a moment too soon.\n\nAre you prepared to defend Dalaran, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[29830] = { id = 29830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containment", description = "My forces are in absolute shambles, and Malygos' assailants just keep coming.\n\nI fear that the worst has yet to come.\n\nYou must engage them until their leader, Cyanigosa, comes. Only her death will stop the invasion and save Dalaran.\n\nSpeak to me again when you are ready.", sourceObjective = "Lieutenant Sinclari in the Violet Hold wants you to put an end to the blue dragon invasion force. You are to speak to her again once Cyanigosa is slain.", progress = "Is it over? Were you able to withstand the assault?", completion = "Thank you, hero!\n\nDalaran is safe for another day because of your bravery.", sourceObjectiveStatus = "unverified-source-field" }
quests[29833] = { id = 29833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Business", description = "While it is true that the Prophet of Akali will trouble this world no more, there yet remains work to be done.\n\nThe greater part of Akali's blood has empowered another, and it is in him that the true danger lies.\n\nQuickly, {name}, make your way to Gundrak and speak with Tol'mar. He will be able to direct you further in this cause.", sourceObjective = "Har'koa wants you to speak with Tol'mar in Gundrak.", completion = "Lissen up, mon. Dere be dangerous work ta be done!", sourceObjectiveStatus = "unverified-source-field" }
quests[29834] = { id = 29834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah Must Pay", description = "It musta been da most awful thing I ever seen. Da great Akali - slain right before my eyes. Horrible...\n\nMy job be to observe only. But dis cannot stand! Gal'darah and his followers must pay!\n\nAvenge Akali's death, mon. It be da right thing ta do.", sourceObjective = "Tol'mar wants you to slay Slad'ran, Moorabi, and Gal'darah in Gundrak.", completion = "Ya done it?! Dey be no more?\n\nHere ya go, mon. Take dis gift for bringin' justice to da frozen wastes.", sourceObjectiveStatus = "unverified-source-field" }
quests[29835] = { id = 29835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah Must Pay", description = "Da mighty Akali has been slain, {race}.\n\nMy role in life be to record, not fight. But dis cannot stand! Gal'darah and his followers must pay!\n\nAvenge Akali's death, mon. It be da right thing ta do.", sourceObjective = "Chronicler Bah'Kini wants you to slay Slad'ran, Moorabi, and Gal'darah in Gundrak.", completion = "Ya really did it?\n\nYou surpassed my expectations, mon. Take dis gift for bringin' justice to da frozen wastes.", sourceObjectiveStatus = "unverified-source-field" }
quests[29836] = { id = 29836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Checkin'", description = "There have been fearsome sounds echoing from Gundrak. They have been increasing in volume and frequency of late.\n\nMy long-time student is currently recording events from inside Gundrak. Perhaps you could find the time to check in on her for me?", sourceObjective = "To'kini wants you to speak to Bah'kini in Gundrak.", completion = "To'kini be my cowardly father - too fearful to take up a position so near Gundrak... so he sent me!\n\nDis place be full of troll history. We can't let Gal'darah and his crazed followers keep it hidden forever!", sourceObjectiveStatus = "unverified-source-field" }
quests[29838] = { id = 29838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of a Kind", description = "At first glance, it be lookin' like da same old story here - trolls tappin' into forbidden powah by destroyin' da very beings dey should be worshippin'.\n\nIf what I learned be true, den dey have a special golem - one like nuthin' created before!\n\nBring me back a piece from dat golem ta study.", sourceObjective = "Chronicler Bah'Kini wants you to recover a piece of the Drakkari Colossus in Gundrak.", progress = "You get me a piece of dat golem, mon?", completion = "Ahh, yeah mon! Dat be what I'm lookin' for.\n\nHere ya go - take somethin' nice for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[29839] = { id = 29839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of a Kind", description = "Dis whole mess coulda been avoided if da Drakkari had worshipped da gods instead of destroyin' dem.\n\nI heard dat dey have a special golem - one imbued with forbidden powah.\n\nBring me back a piece from dat golem so we can learn from our bruddas and sistahs.", sourceObjective = "Tol'mar wants you to recover a piece of the Drakkari Colossus in Gundrak.", progress = "You find da golem? I'm sure it's in there somewhere.", completion = "Amazin'! Dis be like nothing I've ever seer before.\n\nGood work, mon.", sourceObjectiveStatus = "unverified-source-field" }
quests[29840] = { id = 29840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Posterity", description = "Gundrak looks doomed. You know dis to be true.\n\nIf you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end.\n\nPerhaps one day we be bringin' dem back to der former glory.", sourceObjective = "Chronicler Bah'Kini in Gundrak wants you to collect 6 Drakkari History Tablets.", progress = "You find da Drakkari history tablets, mon?", completion = "You be havin' my thanks, mon.\n\nThese will be very useful to us, I'm sure of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[29844] = { id = 29844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Posterity", description = "Da land of da ice trolls is a shadow of its former glory.\n\nIf you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end.\n\nPerhaps one day we be givin' dis land back to a new line of frost trolls.", sourceObjective = "Tol'mar in Gundrak wants you to collect 6 Drakkari History Tablets.", progress = "You find da Drakkari history tablets, mon?", completion = "We trolls been subject to da splittin' of empires for longer than some races been existin'.\n\nWe always regrow from da ruins.", sourceObjectiveStatus = "unverified-source-field" }
quests[29848] = { id = 29848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forlorn Watcher", description = "I would gladly give my life for the Makers or their creations.\n\nHowever, since Loken's betrayal it seems all of Ulduar has turned on the world. One in particular, the Maiden of Grief, seems to reel in agony at her new orders.\n\nPlease lay her to rest and bring me one of her tears.", sourceObjective = "Kaldir Ironbane in the Halls of Stone has asked you to put the Maiden of Grief to rest and to obtain a Crystal Tear of Grief.", progress = "I wish there were another way, but it seems death is the maiden's only salvation now.", completion = "<Kaldir stares into the crystal in silence for a moment.>\n\nNo being has ever felt such sincere sorrow as the Maiden of Grief has.\n\nLet us remember her spirit as we continue our efforts against Loken.", sourceObjectiveStatus = "unverified-source-field" }
quests[29850] = { id = 29850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupt Constructs", description = "The iron dwarves are busy at work carving out massive stone constructs that I fear will soon be used as powerful weapons.\n\nYou must defeat their overseer, Krystallus, and the dark rune giants already walking the halls before it is too late!", sourceObjective = "Kaldir Ironbane in the Halls of Stone has asked you to kill 3 Dark Rune Giants and Krystallus.", completion = "Well done, {race}.\n\nEvery weapon we can take away from Loken is a great boon to our own war effort.", sourceObjectiveStatus = "unverified-source-field" }
quests[29851] = { id = 29851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion of the Tournament", description = "With this tournament we grow ever closer to our final confrontation with the Lich King.\n\n{name}, fight with valor and honor. Every fighter here has gathered for the common good.\n\nTogether, we will stop Arthas!", sourceObjective = "Highlord Tirion Fordring has tasked you with the completion of the Trial of the Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[29860] = { id = 29860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diametrically Opposed", description = "I shall speak plainly to you, little {race}. My people have not been the same since our ties with Thorim were severed.\n\nVolkhan will not rest until either he, or we, are no more. We only want peace, but it seems we have no choice but war.", sourceObjective = "Stormherald Eljrrin in the Halls of Lightning wants you to defeat Volkhan.", completion = "Volkhan shall haunt the dreams of my people no more.\n\nContinue your efforts, little {race}. In time, I am certain my people will grow to forgive Thorim.", sourceObjectiveStatus = "unverified-source-field" }
quests[29861] = { id = 29861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whatever it Takes!", description = "One way or another, Loken shall fall.\n\nThe honor and glory of his defeat shall be yours.\n\nReturn to me with his lying tongue, and earn my unending gratitude.", sourceObjective = "Stormherald Eljrinn in the Halls of Lightning wants you to defeat Loken. You are then to return to Stormherald Eljrinn with Loken's Tongue.", progress = "Has justice been brought to Loken?", completion = "That vile worm is dead?\n\nYou have turned out to be a great boon to my people, little {race}.\n\nPlease accept this gift in return for your loyal friendship.", sourceObjectiveStatus = "unverified-source-field" }
quests[29862] = { id = 29862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Way", description = "Loken's forces prepare for war. What they are not ready for is to be attacked themselves.\n\nNow is the moment to strike. Take out General Bjarngrim and his army, lest they mount an offensive on all life on Azeroth!", sourceObjective = "Stormherald Eljrrin in the Halls of Lightning wants you to kill 3 Stormforged Menders, 3 Stormforged Tacticians, and General Bjarngrim.", progress = "Have you vanquished their forces?", completion = "Though few outside of us shall ever know it, you have certainly saved the world on this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[29863] = { id = 29863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormherald Eljrrin", description = "I have sent an emissary to the Halls of Lightning to take the battle to Loken.\n\nHe undoubtedly needs assistance, given the strength of Loken's armies. Lend him any aid you can so that we may finally stop the traitor.", sourceObjective = "King Jokkum wants you to enter the Halls of Lightning and speak with Stormherald Eljrrin.", completion = "Our time to act is short. Loken prepares for war.", sourceObjectiveStatus = "unverified-source-field" }
quests[29864] = { id = 29864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Working at the Source", description = "We are hard at work ensuring that we minimize our losses to the Scourge war machine.\n\nThe vrykul here are undermining that mission by willingly joining the Lich King's ranks.\n\nPlease, brave champion, you must defeat their spiritual leader, Svala, before she leads her people into the eternal shadow!", sourceObjective = "Argent Confessor Paletress wants you to slay Svala Sorrowgrave.", progress = "I have faith in you, {name}.", completion = "Every soldier we deny to the Scourge is more than one life saved.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30110] = { id = 30110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raid Finder (1st)" }
quests[30111] = { id = 30111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raid Finder (Nth)" }
quests[30112] = { id = 30112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Score to Settle", description = "Utgarde's forces are organizing under the advisory of Prince Keleseth, a san'layn ambassador of the Scourge.\n\nWe cannot allow the vrykul to benefit from his counsel any further. Silence him.", sourceObjective = "Dark Ranger Marrah wants you to slay Prince Keleseth inside Utgarde Keep.", completion = "Revenge feels good.  To think that this is but a taste of what's to come.\n\nArthas will get what he deserves soon enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[30120] = { id = 30120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Drak'Tharon", description = "'Ey, mon, you be here! Dis is good, mon!\n\nDrak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. In return for your help, the keep's most valuable treasures be yours, mon!\n\nOnce ya be reachin' its top, ya must summon me, and I'll perform the ritual.\n\nAlas, my summonin' will be comin' at a cost. Ya must collect mojo from the survivors.", sourceObjective = "Drakuru wants you to use Drakuru's Elixir at his brazier inside Drak'Tharon. Using Drakuru's Elixir there will require 5 Enduring Mojo.\n\nProvided item:", completion = "We done a great thing, mon! And dis just be da beginning....\n\nSeek me out in Zul'Drak when da time be right.\n\nDere be a war to be won, mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[30173] = { id = 30173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War Pigs!" }
quests[30177] = { id = 30177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Heroic Random (1st) (Cataclysm)" }
quests[30538] = { id = 30538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fun for the Little Ones" }
quests[60860] = { id = 60860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Reward has Arrived!" }
quests[63448] = { id = 63448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deluxe Delivery", sourceObjective = "Greetings {name}, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[63450] = { id = 63450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deluxe Delivery", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have these rewards in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose any of these items, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[63767] = { id = 63767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imp in a Ball", sourceObjective = "Greetings {class}, I've been expecting you. An acquaintance of mine asked me to give you something when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose this item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[63768] = { id = 63768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imp in a Ball", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have this reward in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose this item, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[63770] = { id = 63770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Thanks", sourceObjective = "Greetings {name},\n\nWe have a special gift of appreciation for being a passionate collector! We would like to present you with this small yet feisty friend.  May he lead you to new adventures through the Dark Portal and into Outland!", sourceObjectiveStatus = "unverified-source-field" }
quests[63865] = { id = 63865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Thanks", sourceObjective = "Greetings {name},\n\nWe have a special gift of appreciation for being a passionate collector! We would like to present you with this small yet feisty friend.  May he lead you to new adventures through the Dark Portal and into Outland!", sourceObjectiveStatus = "unverified-source-field" }
quests[63866] = { id = 63866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming the Light", description = "Take this vessel, {name}. Invoking its magic will allow you to take this creature's power and claim it for yourself. With it, you will be able to restore your fallen comrade to life.\n\nThere are those who would say what we're doing is wrong, but much of what has befallen us is also wrong. Would they have us throw away such a gift?\n\nThey do not complain when our power is used to prevent the further destruction of Silvermoon. No, they object when they are safe from harm and indulging their magic addictions.", sourceObjective = "Use the Shimmering Vessel on M'uru to fill it and return to Knight-Lord Bloodvalor in Silvermoon City.", progress = "Have you spoken with Magister Astalor Bloodsworn?", completion = "Well done, {name}. The powers granted by the Light have never come 'naturally' to the Blood Knights, but we are not so weak-willed as to let nature dictate to us.\n\nOur mastery of the arcane has provided a path to help see us through these harsh times. Power no longer flows freely in these halls, but it is there for the tenacious and strong of will. Few have the stomach or the aptitude to master it these days, but I know you will not disappoint the order.", sourceObjectiveStatus = "unverified-source-field" }
quests[63978] = { id = 63978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloak and Daggers", description = "As a Rogue, you specialize in striking from the shadows, dispatching foes with a variety of poisons and bleeding attacks. Use Stealth to sneak around and then speak with me when your ready for more training.", sourceObjective = "Use Stealth to sneak around.", sourceObjectiveStatus = "unverified-source-field" }
quests[64028] = { id = 64028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to the city of Stormwind, capital of the Alliance! \n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Stormwind.", completion = "Ready for your training, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[64031] = { id = 64031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools for Survival", description = "Before we begin, you need to be equipped with weapons and armor suited to your talents. The life of an adventurer is never dull, and you never know what will happen next!\n\nI've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", sourceObjective = "Open the survival kit and equip a weapon.", completion = "You look prepared! Let us move onto your first lesson in combat training.", sourceObjectiveStatus = "unverified-source-field" }
quests[64034] = { id = 64034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "As you grow in power, so does your capabilities of being a skillful {class}.\n\nYou can find trainers all around Azeroth, and in capital cities such as here in Stormwind, Darnassus, or Ironforge.\n\nThere's a price to this knowledge, but I will reimburse you just this once. When you are ready, speak with me again to train your abilities.", sourceObjective = "Train a spell by speaking to a {class} trainer.", progress = "When you are ready, speak with me again to train your abilities.", completion = "You look stronger already, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64035] = { id = 64035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", sourceObjective = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're ready for battle, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[64037] = { id = 64037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastern Plaguelands", description = "By the order of Highlord Bolvar Fordragon, all able-bodied citizens of the Alliance are to report to Lord Barthalomew at Light's Hope Chapel.\n\nThe Argent Dawn needs your help to win back the Eastern Plaguelands from the grasp of the scourge.\n\nTo reach the Eastern Plaguelands, speak to the Gryphon Master, Dungar Longdrink, and his gryphons can get you there faster than even the swiftest horse.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Travel to the Eastern Plaguelands and find Leonid Barthalomew. He awaits your arrival at Light's Hope Chapel.", completion = "Perhaps you can help, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64038] = { id = 64038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Portal", description = "There exists a hellish gate that has loomed silent for years, but it is silent no longer.\n\nBy the order of Highlord Bolvar Fordragon, all able-bodied citizens of the Alliance are to report to the Blasted Lands. Speak to Dungar Longdrink, the Gryphon Master to arrange a flight.\n\nOnce at the Blasted Lands, report to Watch Commander Relthorn Netherwane. He awaits you before the Dark Portal...", sourceObjective = "Find Watch Commander Relthorn Netherwane at the Blasted Lands. He awaits your arrival before the Dark Portal.", completion = "Welcome to the nightmare!", sourceObjectiveStatus = "unverified-source-field" }
quests[64046] = { id = 64046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to Orgrimmar, capital of the Horde!\n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Orgrimmar.", completion = "Ready for your training, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[64047] = { id = 64047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to Thunder Bluff, capital to the Tauren!\n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Thunder Bluff.", completion = "Ready for your training?", sourceObjectiveStatus = "unverified-source-field" }
quests[64048] = { id = 64048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools for Survival", description = "Before we begin, you need to be equipped with weapons and armor suited to your talents. The life of an adventurer is never dull, and you never know what will happen next!\n\nI've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", sourceObjective = "Open the survival kit and equip a weapon.", progress = "I've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", completion = "You look prepared! Let us move onto your first lesson in combat training.", sourceObjectiveStatus = "unverified-source-field" }
quests[64049] = { id = 64049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools for Survival", description = "Before we begin, you need to be equipped with weapons and armor suited to your talents. The life of an adventurer is never dull, and you never know what will happen next!\n\nI've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", sourceObjective = "Open the survival kit and equip a weapon.", progress = "I've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", completion = "You look prepared! Let us move onto your first lesson in combat training.", sourceObjectiveStatus = "unverified-source-field" }
quests[64050] = { id = 64050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "As you grow in power, so does your capabilities of being a skillful {class}.\n\nYou can find trainers all around Azeroth, and in capital cities such as here in Orgrimmar, Thunder Bluff, or the Undercity.\n\nThere's a price to this knowledge, but I will reimburse you just this once. When you are ready, speak with me again to train your abilities.", sourceObjective = "Train a spell by speaking to a {class} trainer.", progress = "When you are ready, speak with me again to train your abilities.", completion = "You look stronger already, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64051] = { id = 64051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "As you grow in power, so does your capabilities of being a skillful {class}.\n\nYou can find trainers all around Azeroth, and in capital cities such as here in Thunder Bluff, Orgrimmar, or the Undercity.\n\nThere's a price to this knowledge, but I will reimburse you just this once. When you are ready, speak with me again to train your abilities.", sourceObjective = "Train a spell by speaking to a {class} trainer.", progress = "When you are ready, speak with me again to train your abilities.", completion = "You look stronger already, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64052] = { id = 64052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", progress = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're ready for battle, {name}!" }
quests[64053] = { id = 64053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", progress = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're almost ready for battle, {name}!" }
quests[64063] = { id = 64063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Portal", description = "There exists a hellish gate that has loomed silent for years, but it is silent no longer. \n\nAll able bodied members of the Horde are hereby ordered to report to the Blasted Lands. Visit the Zeppelin Master outside of the city gates of Orgrimmar and ride to Grom'gol Base Camp. From there, speak to Thysta to arrange a flight to Stonard.\n\nReport to Warlord Dar'toon at once. He awaits you before the Dark Portal...", sourceObjective = "Find Watch Warlord Dar'toon at the Blasted Lands. He awaits your arrival before the Dark Portal.", completion = "Welcome to the nightmare!", sourceObjectiveStatus = "unverified-source-field" }
quests[64064] = { id = 64064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastern Plaguelands", description = "All able bodied members of the Horde are hereby ordered to report to Leonid Barthalomew at Light's Hope Chapel.\n\nThe Argent Dawn has reinforced its presence in the Plaguelands and it needs your help to consolidate its victories.\n\nVisit Zeppelin Master Frezza outside the city's main gate and travel to the Undercity. From there, make your way to Light's Hope Chapel in the Eastern Plaguelands.\n\nDestiny calls!", sourceObjective = "Travel to the Eastern Plaguelands and find Leonid Barthalomew. He awaits your arrival at Light's Hope Chapel.", completion = "Perhaps you can help, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64128] = { id = 64128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastern Plaguelands", description = "All able bodied members of the Horde are hereby ordered to report to Leonid Barthalomew at Light's Hope Chapel.\n\nThe Argent Dawn has reinforced its presence in the Plaguelands and it needs your help to consolidate its victories.\n\nSpeak to Tal, the Wind Rider Master to fly to Orgrimmar. From there, visit Zeppelin Master Frezza outside the city's main gate and travel to the Undercity. It is there where you can make your way to the Eastern Plaguelands.\n\nDestiny calls!", sourceObjective = "Travel to the Eastern Plaguelands and find Leonid Barthalomew. He awaits your arrival at Light's Hope Chapel.", completion = "Perhaps you can help, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64139] = { id = 64139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Summons from Lady Liadrin", description = "Your dedication to our order and advancement through the ranks has not gone unnoticed. In fact, Lady Liadrin, leader of the Blood Knights, has asked to speak with you.\n\nThis is a rare honor, {name}. Normally, Lady Liadrin leaves the management of the order's rank-and-file to me, but she has taken a personal interest in you. Do not tarry, {name}.", sourceObjective = "Speak with Lady Liadrin in Silvermoon City.", completion = "We will discuss the purpose for your visit soon. First, let me say that I am indeed impressed by your service and your skill in wielding the Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[64140] = { id = 64140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master's Path", description = "Within the ranks of my order, there exists an inner circle of elite knights. Members of the circle represent the most dedicated, skilled, and trustworthy of all Blood Knights and are handpicked by the leadership. Most simply know the masters by their thalassian charger mounts.\n\nEach candidate for membership must have a sponsor within the circle and must demonstrate their dedication to the order's central tenets.\n\nI have chosen to sponsor you for standing as a Blood Knight master, if this is your wish.", sourceObjective = "Speak with Lady Liadrin again to accept her offer of sponsorship.", completion = "That you have chosen to accept my offer speaks well of you, {name}. I wish you luck in the tasks I am about to set for you, but I'm certain you'll prove yourself more than capable.\n\nI will present the tasks in order from easiest to most difficult and we may begin when you are prepared.", sourceObjectiveStatus = "unverified-source-field" }
quests[64141] = { id = 64141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gesture of Commitment", description = "A Blood Knight's loyalty does not stop at the end of <his/her> blade, {name}. The order asks more of its members than mere drilling and combat. A true knight contributes to all of the order's activities, even the ones that may not seem glorious on the surface.\n\nThis first task is neither combat intensive, nor glorious, but without such contributions, the order would fall apart. I will give you a list of items Magister Astalor Bloodsworn's men require to keep us supplied with Light energy for our magics.", sourceObjective = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Sungrass, 5 Dark Runes, and 150 Gold to Lady Liadrin in Silvermoon City.", progress = "Have you returned with the materials Magister Astalor requires?", completion = "Excellent. It appears everything is here.\n\nDon't worry, your next task will include plenty of opportunities to wield your weapon again, I promise.\n\nI'll have an initiate bring it all to Magister Astalor. There's no need to send you on such a trivial errand when there are more important things to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[64142] = { id = 64142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Demonstration of Loyalty", description = "We Blood Knights are bound to defend Quel'Thalas, {name}. This is a central part of your training. Our enemies are fierce and unrelenting. Silvermoon and its people remain free by our efforts and the support of our allies.\n\nI have received some disturbing reports of a renewed Scourge presence to the southeast of our border with the Eastern Plaguelands. A company of Scourge siege engineers and their equipment appear to be staging for an attack on the Ghostlands. They must not be permitted to succeed.", sourceObjective = "Lady Liadrin in Silvermoon City wants you to destroy 3 Scourge Meat Wagons and kill 15 Scourge Siege Engineers.", completion = "You have done well in demonstrating your loyalty to your homeland and dedication to the needs of the order, {name}. I have one last task for you before you may lay claim to the title of master.", sourceObjectiveStatus = "unverified-source-field" }
quests[64143] = { id = 64143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Masters of the Light", description = "A Blood Knight master possesses incredible skill at wielding and weaving the Light in a way that other so-called 'paladins' can never comprehend. It doesn't stop them from despising us for unleashing the Light's true potential.\n\nWe must send them a message and show them that we are not to be trifled with. What I have in mind will be neither brief nor easy, but if you are committed, the first step will be to infiltrate the library wing of the Tyr's Hand Abbey and procure a vial of Tyr's Hand holy water.", sourceObjective = "Lady Liadrin in Silvermoon City wants you to bring her a vial of Tyr's Hand Holy Water.", progress = "Were you able to get the water?", completion = "Hmm... this is a rather small amount, but if we're careful, it should be sufficient. You see, the Scarlet Crusade believes itself dedicated to the Light. I suppose they still are, in a twisted sort of way, and that's exactly what I'm hoping to capitalize on.\n\nTheir misguided zeal has even tainted the blessing spoken over this water, making it ideal for our purpose.", sourceObjectiveStatus = "unverified-source-field" }
quests[64144] = { id = 64144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Masters of the Light", description = "Now that we have the water, we're going to need a number of reagents in precise quantities. Some of these substances are rare and expensive, {name}, but I have located sources for two.\n\nYou should be able to purchase some arcane catalyst from Zalle, the reagent vendor in one of the shops on the plaza near the Dead Scar. Darlia, the poison merchant near the rogue trainers on Murder Row, stocks crepuscular powder.\n\nTo complete my mixture, I'll also need an azerothian diamond and a pristine black diamond.", sourceObjective = "Lady Liadrin in Silvermoon City wants you to bring her 1 Arcane Catalyst, 1 Crepuscular Powder, 1 Azerothian Diamond, and 1 Pristine Black Diamond.", progress = "Have you gathered the reagents I'll need?", completion = "Now that we have all the reagents, I can prepare the mixture.\n\n<A slow smile spreads across Lady Liadrin's face.>\n\nIt's all coming together perfectly, {name}. When this is finished, I'll give you the details about what remains to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[64217] = { id = 64217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Portal", description = "There exists a hellish gate that has loomed silent for years, but it is silent no longer. \n\nAll able bodied members of the Horde are hereby ordered to report to the Blasted Lands. Visit the Zeppelin Master outside of the city gates of Orgrimmar and ride to Grom'gol Base Camp. From there, speak to Thysta to arrange a flight to Stonard.\n\nReport to Warlord Dar'toon at once. He awaits you before the Dark Portal...", sourceObjective = "Find Watch Warlord Dar'toon at the Blasted Lands. He awaits your arrival before the Dark Portal.", completion = "Welcome to the nightmare!", sourceObjectiveStatus = "unverified-source-field" }
quests[64319] = { id = 64319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Study in Power", description = "Do not think me unduly harsh, {name}. Stillblade knew well what he was being sent to do. He understood and accepted his duty and is an example for all aspiring Blood Knights.\n\nMy words are no eulogy, {name}. Stillblade's service to us is far from over and you will be the instrument of his resurrection.\n\nYour education in the use of the Light has focused on mere charms and parlor tricks thus far. The time has come for you to learn of the nature and breadth of our power. Seek out Magister Astalor Bloodsworn.", sourceObjective = "Speak with Magister Astalor Bloodsworn in the hidden chamber beneath Blood Knight headquarters.", completion = "Welcome, young {class}.\n\nThe power of the Blood Knights is taken from a being of immense power.\n\n\n\nIsn't it magnificent? 'Twas a gift from our beloved Prince Kael'thas, and it is the foundation of the Blood Knights' mastery of the Light. This creature begrudges us its power, so we have devised a method for claiming it on our own terms.", sourceObjectiveStatus = "unverified-source-field" }
quests[64845] = { id = 64845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance War Effort", description = "War is upon us and the Alliance is in need of more combatants to crush the Horde!\n\nOur mission is to disrupt their operations in all of our active battlegrounds.\n\nYe've come to enlist, right?", sourceObjective = "Win a battleground match and return to an Alliance Brigadier General at any Alliance capital city or Shattrath.", progress = "Tell me, {name}.  What news do you bring from the front?", completion = "Excellent news, {class}!  If our tactical deployments continue to be this successful, the Horde will be in full retreat before long.", sourceObjectiveStatus = "unverified-source-field" }
quests[65221] = { id = 65221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purchase 1 Unstable Flask of the Sorcerer for the cost of 10 Apexis Shards" }
quests[65222] = { id = 65222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purchase 5 Unstable Flasks of the Sorcerer for the cost of 50 Apexis Shards" }
quests[65223] = { id = 65223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purchase 1 Unstable Flask of the Beast for the cost of 10 Apexis Shards" }
quests[65224] = { id = 65224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purchase 1 Unstable Flask of the Beast for the cost of 10 Apexis Shards" }
quests[65284] = { id = 65284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Gumbo Kettle", sourceObjective = "Greetings {class}, I've been expecting you. An acquaintance of mine asked me to give you something when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose this item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[65285] = { id = 65285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Gumbo Kettle", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have this reward in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose this item, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[65561] = { id = 65561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabard of Flame", sourceObjective = "Greetings {class}, I've been expecting you. An acquaintance of mine asked me to give you something when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose this item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[65562] = { id = 65562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabard of Flame", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have this reward in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose this item, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[65593] = { id = 65593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hearts of the Lovers", description = "An incubus will be drawn to the hearts of lovers, and the most aching love will create the most irresistible lure.\n\nMy scrying has revealed two that should serve exceptionally.\n\nIn Silverpine Forest, Avelina Lilly provides her tailoring services to the fallen wizards at Ambermill. In the Barrens, Isaac Pearson hopes to make his mark in the seaside town of Ratchet.\n\nThey toil on opposite ends of the world, yet their hearts yearn only for each other. Bring those hearts to Carendin.", sourceObjective = "Bring the hearts of Avelina Lilly and Isaac Pearson to Carendin Halgar in the Temple of the Damned.", progress = "Ah, {name}, you return. Were you able to procure the lovers' hearts?", completion = "As expected. Excellently done, {name}.\n\n\n\nIdiots.", sourceObjectiveStatus = "unverified-source-field" }
quests[65597] = { id = 65597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "The time has come at last. Bring the hearts to the summoning circle below. Place them at its center and call forth the incubus.\n\nThe demon will not be pleased when it realizes that you have tempted it into a trap. Do not fall prey to its beguilement, {name}. You must subdue it fully.\n\nOnly then can I teach you the spell to bind it to your will.", sourceObjective = "Using the Lovers' Hearts, summon and subdue an incubus, then return the Lovers' Hearts to Carendin Halgar in the Magic Quarter of the Undercity.", progress = "The incubus possesses martial prowess, but its illusory charms are its most potent weapon. Falter for even a moment, and the demon will seize upon the opportunity to enthrall you.\n\nDo not let it, {name}.", completion = "Impressive. Very impressive. The sayaad specialize in preying upon mortals. Many a {class} has thought themselves strong enough to command one, only to find themselves being commanded instead.\n\nThis trial did not break you, {name}, and your efforts have earned your reward. I will teach you the spell to summon the incubus.", sourceObjectiveStatus = "unverified-source-field" }
quests[65601] = { id = 65601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love Hurts", description = "A sayaad male is known as an incubus. A creature of profound evil and singular mind.\n\nThe demon must be lured into our world with an item of enticement - an object that represents great love and devotion.\n\nIf you trust a blind man to lead you, {name}, then listen. East from the Cleft of Shadow, along the main drag of Orgrimmar, lives Magar. He longs for the return of his mate, Krilge.\n\nSeek him out. He'll ask you to search for something precious. That is the key which you must bring to Gan'rul.", sourceObjective = "Speak with Magar in Orgrimmar.", completion = "Who told you about Krilge? Have you come with any news? You better not be toying with me...", sourceObjectiveStatus = "unverified-source-field" }
quests[65602] = { id = 65602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is Love?", description = "You will need a powerful reagent to tempt an incubus -- an object that represents great devotion and love.\n\nWith my scrying, I have located a small figurine that should be suitable for your ritual.\n\nThousands of years ago, the figurine belonged to a young couple. The original owners are no more, but their keepsake has survived to the present day.\n\nFollow the road north into Ashenvale, then west and past Maestra's Post. You will see a house nestled amongst the trees. There you will find what you seek.", sourceObjective = "Retrieve the Wooden Figurine and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.", progress = "You've returned. Successfully, I assume?", completion = "<Gakin turns the wooden figurine over in his hand.>\n\nI sense the emotional energy residing within this artifact, undiminished by the passing of time. The incubus will be drawn to it like a fly to honey.\n\nTakar never disappoints.", sourceObjectiveStatus = "unverified-source-field" }
quests[65603] = { id = 65603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "The time has come. Take the figurine and descend into the crypts below. A summoning circle has been prepared, and you must place the figurine at its center.\n\nThen the gateway will open, and the incubus will cross into our world.\n\nA sayaad is not to be underestimated. The demon will not hesitate to attack when it realizes your ruse. You must draw upon all you have been taught to defeat it.\n\nIf you succeed, return to me and I shall bind the creature to your will. Fail, and your soul is forfeit.", sourceObjective = "Using the Wooden Figurine, summon and subdue an incubus, then return the Wooden Figurine to Gakin the Darkbinder in the Slaughtered Lamb.", progress = "The incubus will try to lower your guard through beguilement and deception. The demon is adept at swaying the hearts of mortals.\n\nRemember that anything it may offer you is false. To the demon, you are merely prey.", completion = "Not bad, {name}. Your have bested the fiend, and your will remains unbroken.\n\nMany a {class} has believed themselves strong enough to bind a sayaad, only to become the demon's next meal instead. I am pleased to see you are not so foolish.\n\nWatch closely, and I will teach you the invocation to call upon your newly bound incubus.", sourceObjectiveStatus = "unverified-source-field" }
quests[65604] = { id = 65604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Binding", description = "Yes... I see. I feel the residual emotions bound within these threads. Love is woven into its stitches. The incubus will not be able to resist.\n\nTake this to the summoning circle in Neeru's tent, {name}. Summon forth a malevolent incubus, then show it your mastery. Do not expect it to be subdued quietly. Ready your magic and prepare yourself for a fight. Underestimating a demon has been many a warlock's final mistake.\n\nWhen you have defeated it, return the cloth to me. I will let Magar know what you found.", sourceObjective = "Using the Withered Scarf, summon and subdue an incubus, then return the Withered Scarf to Gan'rul Bloodeye in Orgrimmar.", progress = "The sayaad are dominators of minds and torturers of souls. Their visage brings the heart joy, leaving you defenseless when they rend your flesh with whip and claw.\n\nDo not entertain the incubus' charms, {name}. Slay it quickly and let it be done.", completion = "Hah! Victorious, as expected!\n\nThe incubus is subdued, and it will be my pleasure to teach you to summon the demon. Your strength is growing, and I have no doubt that this is a mere stepping stone to even greater powers.\n\nI will return the scarf to Magar. I have known that {race} for many years, and never did I think he would care for someone the way he cared for Krilge.\n\nIt is a reminder of what separates us from the demons. We wield their darkness, but they will never wield us.", sourceObjectiveStatus = "unverified-source-field" }
quests[65610] = { id = 65610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wish You Were Here", description = "I met Krilge while making Mooncloth in Ashenvale. He was stationed there to protect civilians from danger, until he disappeared...\n\nThey've stopped looking for him and consider him a deserter, but I don't believe it.\n\nWe would often meet at Fallen Sky Lake before it became overrun by those aggressive bog beasts.\n\nI'm not typically one to ask favors, but if you could go to Ashenvale and look for any sign of him, I'd appreciate it.", sourceObjective = "Investigate Fallen Sky Lake in Ashenvale and report your findings to Gan'rul Bloodeye in Orgrimmar.", progress = "Yes, what is it?", completion = "What is it you have there, {name}? A scarf made of... Mooncloth? You best not be seeking to romance me.", sourceObjectiveStatus = "unverified-source-field" }
quests[70344] = { id = 70344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath (80) E" }
quests[70347] = { id = 70347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath (80) E" }
quests[70348] = { id = 70348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath (80) E" }
quests[70354] = { id = 70354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northrend Expedition Supplies", sourceObjective = "Greetings {name}, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[70356] = { id = 70356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northrend Expedition Supplies", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have these rewards in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose any of these items, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[70395] = { id = 70395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to the city of Stormwind, capital of the Alliance! \n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Stormwind.", completion = "Ready for your training, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[70396] = { id = 70396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to Orgrimmar, capital of the Horde!\n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Orgrimmar.", completion = "Ready for your training, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[70397] = { id = 70397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools for Survival", description = "Before we begin, you need to be equipped with weapons and armor suited to your talents. The life of an adventurer is never dull, and you never know what will happen next!\n\nI've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", sourceObjective = "Open the survival kit and equip a weapon.", progress = "I've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", completion = "You look prepared! Let us move onto your first lesson in combat training.", sourceObjectiveStatus = "unverified-source-field" }
quests[70398] = { id = 70398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "As you grow in power, so does your capabilities of being a skillful {class}.\n\nYou can find trainers all around Azeroth, and in capital cities such as here in Stormwind, Darnassus, or Ironforge.\n\nThere's a price to this knowledge, but I will reimburse you just this once. When you are ready, speak with me again to train your abilities.", sourceObjective = "Train a spell by speaking to a {class} trainer.", progress = "When you are ready, speak with me again to train your abilities.", completion = "You look stronger already, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70401] = { id = 70401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", sourceObjective = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're ready for battle, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[70411] = { id = 70411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Dockmaster", description = "The Lich King must pay for the atrocities he has unleashed across our lands!\n\nBy the order of King Varian Wrynn, you have been called upon to take arms and aid in the Alliance's campaign in gaining a foothold in the treacherous continent of Northrend.", sourceObjective = "Use a scroll of teleportation from your inventory to reach the harbor and speak to the dock master.", completion = "Greetings, {class}. A Northrend-bound ship should be arriving at the end of this dock shortly. Hop aboard and the ship's crew will transport you to that frozen, wicked island!", sourceObjectiveStatus = "unverified-source-field" }
quests[70448] = { id = 70448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elite Northrend Expedition Supplies", sourceObjective = "Greetings {name}, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[70449] = { id = 70449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elite Northrend Expedition Supplies", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have these rewards in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose any of these items, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[70685] = { id = 70685, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuskarr Kite" }
