quests[70736] = { id = 70736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", progress = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're ready for battle, {name}!" }
quests[70737] = { id = 70737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Zeppelin Master", description = "The Lich King must pay for the atrocities he has unleashed across our lands!\n\nBy the order of Warchief Thrall, you have been called upon to take arms and aid in the Horde's campaign in gaining a foothold in the treacherous continent of Northrend.", sourceObjective = "Use a scroll of teleportation from your inventory to reach the zeppelin tower and speak to the zeppelin master.", completion = "Greetings, {class}. A Northrend-bound zeppelin should be arriving at the end of this platform shortly. Hop aboard and the airship's crew will transport you to that frozen, wicked island!", sourceObjectiveStatus = "unverified-source-field" }
quests[70761] = { id = 70761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tools for Survival", description = "Before we begin, you need to be equipped with weapons and armor suited to your talents. The life of an adventurer is never dull, and you never know what will happen next!\n\nI've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", sourceObjective = "Open the survival kit and equip a weapon.", sourceObjectiveStatus = "unverified-source-field" }
quests[70762] = { id = 70762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to Thunder Bluff, capital to the Tauren!\n\nMeet with a {class} trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", sourceObjective = "Meet with a {class} trainer in Thunder Bluff.", completion = "Ready for your training?", sourceObjectiveStatus = "unverified-source-field" }
quests[70764] = { id = 70764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Training", description = "As you grow in power, so does your capabilities of being a skillful {class}.\n\nYou can find trainers all around Azeroth, and in capital cities such as here in Thunder Bluff, Orgrimmar, or the Undercity.\n\nThere's a price to this knowledge, but I will reimburse you just this once. When you are ready, speak with me again to train your abilities.", sourceObjective = "Train a spell by speaking to a {class} trainer.", sourceObjectiveStatus = "unverified-source-field" }
