quests[70863] = { id = 70863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoplet", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have these rewards in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose any of these items, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[70865] = { id = 70865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Shattrath City", description = "A mysterious message has come for you to travel to a land beyond Azeroth. \n\nHeed the call and investigate what lies in these new lands.", sourceObjective = "Use the scroll of teleportation from your inventory to reach Shattrath City and speak to the mysterious Haggard War Veteran.", completion = "Greetings, {class}. Thank you for answering my summons.", sourceObjectiveStatus = "unverified-source-field" }
