quests[70869] = { id = 70869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", progress = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're ready for battle, {name}!" }
quests[70870] = { id = 70870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talented", description = "Every {class} makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a {class} trainer to rework them.", sourceObjective = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're ready for battle, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[70998] = { id = 70998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frosty", sourceObjective = "Greetings {name}, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[70999] = { id = 70999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frosty", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have these rewards in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose any of these items, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[72201] = { id = 72201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath (80) E" }
